"use client"

import type { StandardSchemaV1 } from "@standard-schema/spec"
import type { ReactNode } from "react"
import type {
  ArrayPath,
  FieldPath,
  FieldPathValue,
  FieldValues,
  UseFieldArrayReturn,
  UseFormReturn,
} from "react-hook-form"

import {
  FormField,
  type FormFieldProps,
  formControlAdapters,
  useFormField,
  type FormControlAdapter,
  type FormFieldState,
} from "@/components/ui/form-field"
import {
  useFormFieldArray,
  useFormInstance,
  useFormWatch,
  type UseFormFieldArrayOptions,
} from "@/components/ui/form-instance"
import { Form, type FormProps, type FormSubmitHelpers } from "@/components/ui/form-root"
import { FieldSet, type FieldSetProps } from "@/components/ui/field"
import {
  FormActions,
  FormRootError,
  type FormActionsProps,
  type FormRootErrorProps,
} from "@/components/ui/form-actions"
import {
  FormServerError,
  createFormMessages,
  formIssueMessage,
  formMessagesEn,
  formMessagesEs,
  resolveFormMessage,
  toFormErrors,
  type FormErrorInput,
  type FormErrors,
  type FormIssue,
  type FormIssueCode,
  type FormMessage,
  type FormMessageDictionary,
  type FormMessages,
} from "@/components/ui/form-messages"

type FormValuesOf<Schema extends StandardSchemaV1> =
  StandardSchemaV1.InferInput<Schema> extends FieldValues ? StandardSchemaV1.InferInput<Schema> : FieldValues

type TypedForm<Schema extends StandardSchemaV1> = {
  Form: (props: FormProps<Schema>) => ReactNode
  /** `name` must be a path into the schema's input. */
  FormField: (props: FormFieldProps<FormValuesOf<Schema>>) => ReactNode
  useFormInstance: () => UseFormReturn<FormValuesOf<Schema>>
  useFormWatch: <Name extends FieldPath<FormValuesOf<Schema>>>(name: Name) => FieldPathValue<FormValuesOf<Schema>, Name>
  useFormFieldArray: <Name extends ArrayPath<FormValuesOf<Schema>>, KeyName extends string = "id">(
    name: Name,
    options?: UseFormFieldArrayOptions<FormValuesOf<Schema>, Name, KeyName>,
  ) => UseFieldArrayReturn<FormValuesOf<Schema>, Name, KeyName>
}

/**
 * The form parts typed by one schema, so a misspelt `name` fails to compile:
 * `const { Form, FormField } = createForm<typeof schema>()`. They are the same components, only typed.
 */
function createForm<Schema extends StandardSchemaV1>(): TypedForm<Schema> {
  return {
    Form,
    FormField,
    useFormInstance,
    useFormWatch,
    useFormFieldArray,
  } as unknown as TypedForm<Schema>
}

export { Form, createForm }
export type { FormProps, FormValuesOf, TypedForm }
export type { FormSubmitHelpers }
export { FieldSet }
export type { FieldSetProps }
export { FormActions, FormRootError }
export type { FormActionsProps, FormRootErrorProps }
export { FormField, formControlAdapters, useFormField }
export type { FormControlAdapter, FormFieldProps, FormFieldState }
export { useFormFieldArray, useFormInstance, useFormWatch }
export type { UseFormFieldArrayOptions }
export {
  FormServerError,
  createFormMessages,
  formIssueMessage,
  formMessagesEn,
  formMessagesEs,
  resolveFormMessage,
  toFormErrors,
}
export type { FormErrorInput, FormErrors, FormIssue, FormIssueCode, FormMessage, FormMessageDictionary, FormMessages }

"use client"

import type { StandardSchemaV1 } from "@standard-schema/spec"
import { createParts } from "@ui-sdk/react/primitive"
import { useMemo, useRef, useState, type FormEvent, type ReactNode } from "react"
import { useForm, type DefaultValues, type FieldValues, type Path, type UseFormReturn } from "react-hook-form"

import { FieldLabelPlacementDefault, type FieldLabelPlacement } from "@/components/ui/field"
import {
  FormContext,
  issueResolver,
  requiredProbe,
  toFieldError,
  type FormContextValue,
  type SubmitInterceptor,
} from "@/components/ui/form-context"
import { toFormErrors, type FormErrorInput, type FormMessages } from "@/components/ui/form-messages"
import { formRoot } from "@/components/ui/form-primitive"
import { useFocusRequest, useReportChange, useRestoreFocusAfterPending } from "@/components/ui/use-form-sync"
import { cn } from "@/lib/utils"

const { Root: FormRoot } = createParts(formRoot, { root: "form" })

type FormSubmitHelpers<Values extends FieldValues> = {
  /** Shows an error on a field, or on the form with `"root"`: text, or `{ code, params }` for `messages`. */
  setError: (name: Path<Values> | "root", error: FormErrorInput) => void
  form: UseFormReturn<Values>
}

type FormProps<Schema extends StandardSchemaV1> = {
  schema: Schema
  defaultValues?: DefaultValues<StandardSchemaV1.InferInput<Schema> & FieldValues>
  /**
   * Runs with the parsed values once they pass the schema. A returned Promise keeps the form pending. A thrown
   * `FormServerError`, `{ fieldErrors, message }` or issue list maps to the fields and the root error; any other
   * error shows its message in `FormRootError`.
   */
  onSubmit: (
    values: StandardSchemaV1.InferOutput<Schema>,
    helpers: FormSubmitHelpers<StandardSchemaV1.InferInput<Schema> & FieldValues>,
  ) => unknown
  /** A dictionary (`formMessagesEs`) or a function of the issue, for any i18n library; English by default. */
  messages?: FormMessages
  /**
   * Words screen readers hear after a required field's label, like "required", in the page's language. Unset, the
   * marker is only visual and the control's own `required` state is announced; set, the words join the field's name.
   */
  requiredLabel?: string
  /** Where each FormField's label sits by default: `top`, or `in`/`on` for its text controls (see Field). */
  labelPlacement?: FieldLabelPlacement
  /** Fields are disabled while `onSubmit` runs; `false` keeps them editable. */
  disableWhilePending?: boolean
  /** The form's accessible name. Without it (or `aria-labelledby`), agents use its fields and buttons only. */
  label?: string
  "aria-labelledby"?: string
  onPendingChange?: (pending: boolean) => void
  onDirtyChange?: (dirty: boolean) => void
  id?: string
  className?: string
  children?: ReactNode
}

const tabbable =
  'input:not([type="hidden"]), textarea, select, button, [tabindex]:not([tabindex="-1"]), [contenteditable="true"]'

function focusTarget(form: HTMLFormElement, root: HTMLElement | null) {
  for (const field of form.querySelectorAll<HTMLElement>('[data-slot="field"][data-invalid]')) {
    for (const candidate of field.querySelectorAll<HTMLElement>(tabbable)) {
      if (candidate.tabIndex < 0 || candidate.matches(":disabled") || candidate.closest('[aria-hidden="true"]'))
        continue
      return candidate
    }
  }
  return root
}

function setFormError(form: UseFormReturn<FieldValues>, name: string, error: FormErrorInput) {
  form.setError(name === "root" ? "root.server" : name, toFieldError(error))
}

// Field errors land on fields that are rendered or hold a value; the rest join the root error.
function applyFormError(form: UseFormReturn<FieldValues>, fields: Map<string, unknown>, error: unknown) {
  const parsed = toFormErrors(error)
  if (!parsed) {
    setFormError(form, "root", error instanceof Error ? error.message : String(error))
    return
  }
  const unmapped: string[] = []
  for (const [name, fieldError] of Object.entries(parsed.fieldErrors ?? {})) {
    if (fields.has(name) || form.getValues(name) !== undefined) setFormError(form, name, fieldError)
    else unmapped.push(typeof fieldError === "string" ? fieldError : (fieldError.message ?? fieldError.code))
  }
  if (parsed.message !== undefined) setFormError(form, "root", parsed.message)
  else if (unmapped.length) setFormError(form, "root", unmapped.join("\n"))
}

// The try/finally lives outside the component: React Compiler 1.0 can't compile a component that holds one.
async function settle<T>(task: () => T | Promise<T>, cleanup: () => void): Promise<T> {
  try {
    return await task()
  } finally {
    cleanup()
  }
}

function Form<Schema extends StandardSchemaV1>({
  schema,
  defaultValues,
  onSubmit,
  messages,
  requiredLabel,
  labelPlacement,
  disableWhilePending = true,
  label,
  "aria-labelledby": labelledBy,
  onPendingChange,
  onDirtyChange,
  id,
  className,
  children,
}: FormProps<Schema>) {
  type Values = StandardSchemaV1.InferInput<Schema> & FieldValues
  const resolver = useMemo(() => issueResolver(schema), [schema])
  const [initialValues] = useState(defaultValues)
  const requires = useMemo(() => requiredProbe(schema, initialValues), [schema, initialValues])
  const form = useForm<Values>({ resolver, defaultValues, shouldFocusError: false })
  const [pending, setPending] = useState(false)
  const [confirm, setConfirm] = useState(false)
  const [focusRequest, setFocusRequest] = useState(0)
  const element = useRef<HTMLFormElement>(null)
  const rootElement = useRef<HTMLElement | null>(null)
  const running = useRef(false)
  const blocked = useRef(false)
  const interceptor = useRef<SubmitInterceptor | null>(null)
  const restoreFocus = useRef<Element | null>(null)
  const [fields] = useState(() => new Map<string, string | undefined>())
  const dirty = form.formState.isDirty

  useReportChange(pending, onPendingChange)
  useRestoreFocusAfterPending(pending, restoreFocus)
  useReportChange(dirty, onDirtyChange)
  useFocusRequest(focusRequest, () => {
    if (element.current) focusTarget(element.current, rootElement.current)?.focus()
  })

  const untyped = form as unknown as UseFormReturn<FieldValues>
  const setError: FormSubmitHelpers<Values>["setError"] = (name, error) => setFormError(untyped, name, error)

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    event.stopPropagation()
    if (running.current || blocked.current) return
    const intercept = interceptor.current
    const beforeSubmit = intercept?.beforeSubmit
    if (beforeSubmit) {
      running.current = true
      const proceed = await settle(beforeSubmit, () => {
        running.current = false
      })
      if (!proceed) return
    }
    running.current = true
    restoreFocus.current = document.activeElement
    let failed = false
    const fail = (error: unknown) => {
      failed = true
      intercept?.onError?.(error)
      applyFormError(untyped, fields, error)
    }
    form.clearErrors("root")
    const submit = form.handleSubmit(
      async (values) => {
        setPending(true)
        await settle(
          async () => {
            try {
              await onSubmit(values as StandardSchemaV1.InferOutput<Schema>, { setError, form })
            } catch (error) {
              fail(error)
            }
          },
          () => setPending(false),
        )
      },
      (errors) => {
        failed = true
        intercept?.onInvalid?.(errors)
      },
    )
    await settle(
      () => submit(event),
      () => {
        running.current = false
        if (failed) {
          restoreFocus.current = null
          setFocusRequest((count) => count + 1)
        }
      },
    )
  }

  const disabled = pending && disableWhilePending
  const context = useMemo<FormContextValue>(
    () => ({
      form: untyped,
      messages,
      labelPlacement,
      requiredLabel,
      requires,
      pending,
      disabled,
      fields,
      setRoot: (root) => {
        rootElement.current = root
      },
      setConfirm,
      setBlocked: (next) => {
        blocked.current = next
      },
      setInterceptor: (next) => {
        interceptor.current = next
      },
      applyError: (error) => applyFormError(untyped, fields, error),
      requestFocus: () => setFocusRequest((count) => count + 1),
    }),
    [untyped, messages, labelPlacement, requiredLabel, requires, pending, disabled, fields],
  )

  return (
    <FormContext.Provider value={context}>
      <FormRoot
        ref={element}
        id={id}
        noValidate
        named={Boolean(label || labelledBy)}
        confirm={confirm}
        onResetRequest={() => form.reset()}
        aria-label={label}
        aria-labelledby={labelledBy}
        aria-busy={pending || undefined}
        data-pending={pending ? "" : undefined}
        onSubmit={handleSubmit}
        onReset={(event: FormEvent<HTMLFormElement>) => {
          event.preventDefault()
          form.reset()
        }}
        className={cn("flex min-w-0 flex-col gap-group", className)}
      >
        <FieldLabelPlacementDefault value={labelPlacement}>{children}</FieldLabelPlacementDefault>
      </FormRoot>
    </FormContext.Provider>
  )
}

export { Form, focusTarget }
export type { FormProps, FormSubmitHelpers }

"use client"

import type { ReactNode } from "react"
import { useFormState } from "react-hook-form"
import { CircleExclamationPointIcon } from "lucide-react"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { errorText, useFormContext, type IssueError } from "@/components/ui/form-context"
import { useFormFlag } from "@/components/ui/use-form-sync"
import { cn } from "@/lib/utils"

type FormRootErrorProps = {
  /** A heading above the message, in the page's language. */
  title?: ReactNode
  className?: string
}

/** The form's own error: a thrown error, a server message or a schema issue with no field. Focused after a submit. */
function FormRootError({ title, className }: FormRootErrorProps) {
  const { form, messages, setRoot } = useFormContext("FormRootError")
  const { errors } = useFormState({ control: form.control, name: "root" })
  const root = errors.root as (IssueError & Record<string, IssueError | undefined>) | undefined
  const lines = [root?.server, root?.message === undefined ? undefined : root]
    .filter((error): error is IssueError => Boolean(error?.message || error?.type))
    .flatMap((error) => errorText(error, "root", undefined, messages).split("\n"))

  if (lines.length === 0) return null
  return (
    <Alert
      ref={setRoot}
      tone="destructive"
      live
      tabIndex={-1}
      data-slot="form-root-error"
      className={cn("outline-none focus-visible:ring-2 focus-visible:ring-ring", className)}
    >
      <CircleExclamationPointIcon />
      {title === undefined ? null : <AlertTitle>{title}</AlertTitle>}
      <AlertDescription>
        {lines.length === 1 ? (
          lines[0]
        ) : (
          <ul className="flex list-disc flex-col gap-inline ps-group">
            {lines.map((line) => (
              <li key={line}>{line}</li>
            ))}
          </ul>
        )}
      </AlertDescription>
    </Alert>
  )
}

type FormActionsTone =
  | { tone?: "default"; confirm?: string }
  | {
      tone: "destructive"
      /** Sentence an agent must show a person before submitting, e.g. "Deletes the project and its files". */
      confirm: string
    }

type FormActionsProps = FormActionsTone & {
  submitLabel: ReactNode
  /** What screen readers hear once the submit has been pending for a second, in the page's language. */
  pendingLabel?: string
  /** The cancel button's text; shown when set. */
  cancel?: ReactNode
  onCancel?: () => void
  /** Another control, like a "Save draft" Button, placed before cancel. */
  secondaryAction?: ReactNode
  /** Disables submit and cancel while something outside the form is busy; the form doesn't submit. */
  disabled?: boolean
  /** Disables only submit, for example until a required upload finishes; the form doesn't submit. */
  submitDisabled?: boolean
  /** Shows the pending look for work the app runs itself (the form's own submit needs nothing); the form doesn't submit. */
  pending?: boolean
  className?: string
}

function FormActions({
  submitLabel,
  pendingLabel,
  cancel,
  onCancel,
  secondaryAction,
  tone = "default",
  confirm,
  disabled = false,
  submitDisabled = false,
  pending: forcedPending = false,
  className,
}: FormActionsProps) {
  const context = useFormContext("FormActions")
  const destructive = tone === "destructive"
  const { setConfirm, setBlocked } = context
  useFormFlag(setConfirm, destructive)
  const blocked = disabled || submitDisabled || forcedPending
  useFormFlag(setBlocked, blocked)
  const pending = context.pending || forcedPending

  return (
    <div
      data-slot="form-actions"
      className={cn(
        "flex flex-wrap items-center justify-end gap-items narrow:flex-col-reverse narrow:items-stretch",
        className,
      )}
    >
      {secondaryAction}
      {cancel === undefined ? null : (
        <Button type="button" variant="outline" disabled={pending || disabled} onClick={onCancel}>
          {cancel}
        </Button>
      )}
      <Button
        type="submit"
        variant={destructive ? "destructive" : "default"}
        loading={pending}
        disabled={(disabled || submitDisabled) && !pending}
        pendingAnnouncement={pendingLabel}
        data-agent-confirm={confirm}
      >
        {submitLabel}
      </Button>
    </div>
  )
}

export { FormActions, FormRootError }
export type { FormActionsProps, FormRootErrorProps }

"use client"

// Internal to Form: its shape changes without notice. Apps import from `@/components/ui/form` (`useFormInstance`,
// `useFormWatch`, `useFormFieldArray`, `useFormField`), never from this file.

import { standardSchemaResolver } from "@hookform/resolvers/standard-schema"
import type { StandardSchemaV1 } from "@standard-schema/spec"
import { createContext, useContext } from "react"
import type { FieldError, FieldErrors, FieldValues, Resolver, UseFormReturn } from "react-hook-form"

import type { FieldLabelPlacement } from "@/components/ui/field"
import {
  issueFromInput,
  issueFromSchema,
  issuePath,
  resolveFormMessage,
  type FormErrorInput,
  type FormIssue,
  type FormMessages,
} from "@/components/ui/form-messages"

type SubmitInterceptor = {
  /** `false` stops the submit before validation. */
  beforeSubmit?: () => boolean | Promise<boolean>
  onInvalid?: (errors: FieldErrors) => void
  onError?: (error: unknown) => void
}

type FormContextValue = {
  form: UseFormReturn<FieldValues>
  messages?: FormMessages
  labelPlacement?: FieldLabelPlacement
  pending: boolean
  disabled: boolean
  fields: Map<string, string | undefined>
  setRoot: (root: HTMLElement | null) => void
  setConfirm: (confirm: boolean) => void
  /** FormActions holds submits while it is disabled or forced pending by the app. */
  setBlocked: (blocked: boolean) => void
  /** A StepForm takes over submits: Next on its earlier steps, and the step to show after errors. */
  setInterceptor: (interceptor: SubmitInterceptor | null) => void
  /** Puts an error in any shape `onSubmit` may throw on its fields and the root error. */
  applyError: (error: unknown) => void
  /** Moves focus to the first invalid field, or the root error, after the next render. */
  requestFocus: () => void
  /** Whether the schema rejects this field when it is empty; `false` when that can't be told synchronously. */
  requires: (name: string) => boolean
  requiredLabel?: string
}

const FormContext = createContext<FormContextValue | null>(null)

function emptyLike(value: unknown) {
  if (value === null) return null
  if (typeof value === "string") return ""
  if (Array.isArray(value)) return []
  if (typeof value === "boolean") return false
  return undefined
}

function withValueAt(values: unknown, path: string[], value: unknown): unknown {
  const [key, ...rest] = path
  if (key === undefined) return value
  const source = values && typeof values === "object" ? (values as Record<string, unknown>) : {}
  const copy = (Array.isArray(source) ? [...source] : { ...source }) as Record<string, unknown>
  copy[key] = withValueAt(source[key], rest, value)
  return copy
}

/**
 * Probes the schema with each field emptied in turn: a field is required when that alone gives it an issue. This
 * reads any Standard Schema, but only one that reports every issue (Zod, Valibot, ArkType) and validates
 * synchronously; an async schema marks nothing.
 */
function requiredProbe(schema: StandardSchemaV1, defaults: unknown) {
  const cache = new Map<string, boolean>()
  return (name: string) => {
    const known = cache.get(name)
    if (known !== undefined) return known
    const path = name.split(".")
    const values = withValueAt(defaults, path, emptyLike(valueAt(defaults, path)))
    let required = false
    try {
      const result = schema["~standard"].validate(values)
      if (!(result instanceof Promise)) required = (result.issues ?? []).some((issue) => issuePath(issue) === name)
    } catch {
      required = false
    }
    cache.set(name, required)
    return required
  }
}

function valueAt(values: unknown, path: string[]) {
  let current = values
  for (const key of path) {
    if (current === null || typeof current !== "object") return undefined
    current = (current as Record<string, unknown>)[key]
  }
  return current
}

function useFormContext(part: string) {
  const context = useContext(FormContext)
  if (!context) throw new Error(`${part} must be inside a Form.`)
  return context
}

type IssueError = FieldError & { params?: Record<string, unknown> }

function errorAt(errors: Record<string, unknown>, path: string) {
  let current: unknown = errors
  for (const key of path.split(".")) {
    if (!current || typeof current !== "object") return undefined
    current = (current as Record<string, unknown>)[key]
  }
  return current as IssueError | undefined
}

/**
 * `standardSchemaResolver` keeps only each issue's message. This wraps the schema to see the issues too, and writes
 * each one's code and params onto the error at its path, so messages can be translated from codes.
 */
function issueResolver(schema: StandardSchemaV1): Resolver<FieldValues> {
  let issues: readonly StandardSchemaV1.Issue[] = []
  const capture = (result: StandardSchemaV1.Result<unknown>) => {
    issues = result.issues ?? []
    return result
  }
  const watched: StandardSchemaV1 = {
    "~standard": {
      ...schema["~standard"],
      validate: (value) => {
        const result = schema["~standard"].validate(value)
        return result instanceof Promise ? result.then(capture) : capture(result)
      },
    },
  }
  const resolve = standardSchemaResolver(watched as StandardSchemaV1<FieldValues>) as Resolver<FieldValues>
  return async (values, context, options) => {
    const result = await resolve(values, context, options)
    const seen = new Set<string>()
    for (const issue of issues) {
      const path = issuePath(issue)
      if (seen.has(path)) continue
      seen.add(path)
      const error = errorAt(result.errors, path)
      if (!error) continue
      const parsed = issueFromSchema(issue, values)
      error.type = parsed.code
      error.params = parsed.params
      error.message = parsed.message
    }
    return result
  }
}

function toFieldError(input: FormErrorInput): IssueError {
  const issue = issueFromInput(input, "")
  return { type: issue.code, message: issue.message, params: issue.params }
}

function issueFromError(error: IssueError, field: string, label?: string): FormIssue {
  return {
    code: error.type || "invalid",
    field,
    label,
    params: error.params ?? {},
    message: error.message,
  }
}

function errorText(
  error: IssueError,
  field: string,
  label: string | undefined,
  ...layers: (FormMessages | undefined)[]
) {
  return resolveFormMessage(issueFromError(error, field, label), ...layers)
}

export { FormContext, errorAt, errorText, issueResolver, requiredProbe, toFieldError, useFormContext }
export type { FormContextValue, IssueError, SubmitInterceptor }

"use client"

import {
  Children,
  cloneElement,
  createContext,
  isValidElement,
  useContext,
  useMemo,
  type ComponentType,
  type ReactElement,
  type ReactNode,
} from "react"
import { useController, type ControllerRenderProps, type FieldValues, type Path } from "react-hook-form"

import { Checkbox } from "@/components/ui/checkbox"
import {
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
  floatingLabelControls,
  formControlAdapters,
  type FieldLabelPlacement,
  type FormControlAdapter,
} from "@/components/ui/field"
import { errorText, useFormContext } from "@/components/ui/form-context"
import type { FormMessages } from "@/components/ui/form-messages"
import { Input } from "@/components/ui/input"
import { Switch } from "@/components/ui/switch"
import { Textarea } from "@/components/ui/textarea"
import { useFieldRegistration } from "@/components/ui/use-form-sync"
import { cn } from "@/lib/utils"

const valueAdapter: FormControlAdapter = { value: "value", change: "onValueChange" }
const textAdapter: FormControlAdapter = { ...valueAdapter, toControl: (value) => value ?? "", blur: true }
const checkedAdapter: FormControlAdapter = {
  value: "checked",
  change: "onCheckedChange",
  toControl: (value) => value ?? false,
}

// Every other registry control (NumberInput, Select, Combobox, RadioGroup, Slider, DatePicker, SegmentedControl,
// ToggleGroup, NativeSelect, DateTimePicker) takes `value` and `onValueChange` as is; TokenInput adds itself.
formControlAdapters
  .set(Input, textAdapter)
  .set(Textarea, textAdapter)
  .set(Checkbox, checkedAdapter)
  .set(Switch, checkedAdapter)

type FormFieldState = {
  name: string
  value: unknown
  onChange: (value: unknown) => void
  onBlur: () => void
  ref: ControllerRenderProps<FieldValues>["ref"]
  invalid: boolean
  /** The error's text, translated. */
  error?: string
  disabled: boolean
  pending: boolean
}

const FormFieldContext = createContext<FormFieldState | null>(null)

/** The field around a custom control: its value, change handler and error. */
function useFormField() {
  const field = useContext(FormFieldContext)
  if (!field) throw new Error("useFormField must be inside a FormField.")
  return field
}

type FormFieldProps<Values extends FieldValues = FieldValues> = {
  /** A path into the form's values, like `email` or `tags.0.label`; typed by `createForm<typeof schema>()`. */
  name: Path<Values>
  label?: ReactNode
  description?: ReactNode
  /** `in` or `on` floats the label inside the control or on its border; the Form's `labelPlacement` by default. */
  labelPlacement?: FieldLabelPlacement
  /**
   * Draws a required marker and sets the control's `required`. Read from the schema by default (a field it rejects
   * when empty); `false` hides the marker.
   */
  required?: boolean
  /** Words screen readers hear after the label; the Form's `requiredLabel` by default. */
  requiredLabel?: string
  disabled?: boolean
  /** Messages for this field only; they win over the form's. */
  messages?: FormMessages
  /** `"checked"` binds `checked`/`onCheckedChange`; an adapter binds any other prop pair. Read from the child by default. */
  bind?: "value" | "checked" | FormControlAdapter
  /** For a control the adapters don't know: render it from the field's state, inside the Field. */
  render?: (field: FormFieldState) => ReactNode
  className?: string
  /** One control, bound by `name`. */
  children?: ReactElement
}

function adapterFor(child: ReactElement, bind: FormFieldProps["bind"]) {
  if (bind === "checked") return checkedAdapter
  if (bind === "value") return valueAdapter
  if (bind) return bind
  return formControlAdapters.get(child.type as ComponentType) ?? valueAdapter
}

function chain(own: unknown, bound: (...args: unknown[]) => void) {
  return (...args: unknown[]) => {
    if (typeof own === "function") own(...args)
    bound(...args)
  }
}

function RequiredMarker({ label }: { label: string | undefined }) {
  return (
    <>
      {" "}
      <span data-slot="form-field-required" className="text-destructive">
        <span aria-hidden="true">*</span>
        {label === undefined ? null : <span className="sr-only">{` ${label}`}</span>}
      </span>
    </>
  )
}

function FormField<Values extends FieldValues = FieldValues>({
  name,
  label,
  description,
  labelPlacement,
  required: requiredProp,
  requiredLabel,
  disabled,
  messages,
  bind,
  render,
  className,
  children,
}: FormFieldProps<Values>) {
  const context = useFormContext("FormField")
  const required = requiredProp ?? context.requires(name)
  const { field, fieldState } = useController({ name, control: context.form.control })
  const textLabel = typeof label === "string" ? label : undefined

  useFieldRegistration(context.fields, name, textLabel)

  const error = fieldState.error
  const message = error ? errorText(error, name, textLabel, messages, context.messages) : undefined
  const fieldDisabled = Boolean(disabled) || context.disabled
  const state = useMemo<FormFieldState>(
    () => ({
      name,
      value: field.value,
      onChange: field.onChange,
      onBlur: field.onBlur,
      ref: field.ref,
      invalid: Boolean(error),
      error: message,
      disabled: fieldDisabled,
      pending: context.pending,
    }),
    [name, field.value, field.onChange, field.onBlur, field.ref, error, message, fieldDisabled, context.pending],
  )

  let control: ReactNode = render?.(state)
  let checkedLayout = false
  let floats = false
  if (!render) {
    const child = Children.only(children)
    if (!isValidElement<Record<string, unknown>>(child)) throw new Error("FormField needs one control as its child.")
    const adapter = adapterFor(child, bind)
    checkedLayout = adapter === checkedAdapter
    floats = floatingLabelControls.has(child.type as object)
    control = cloneElement(child, {
      name: child.props.name ?? name,
      required: child.props.required ?? (required || undefined),
      [adapter.value]: adapter.toControl ? adapter.toControl(field.value) : field.value,
      [adapter.change]: chain(child.props[adapter.change], (value) =>
        field.onChange(adapter.fromControl ? adapter.fromControl(value) : value),
      ),
      ...(adapter.blur ? { onBlur: chain(child.props.onBlur, field.onBlur) } : {}),
    })
  }

  // A form's default reaches only controls that can hold a floating label; a checkbox or switch never floats.
  const placement = checkedLayout ? "top" : (labelPlacement ?? (floats ? context.labelPlacement : undefined) ?? "top")
  const fieldLabel =
    label === undefined ? null : (
      <FieldLabel>
        {label}
        {required ? <RequiredMarker label={requiredLabel ?? context.requiredLabel} /> : null}
      </FieldLabel>
    )
  return (
    <FormFieldContext.Provider value={state}>
      <Field
        name={name}
        labelPlacement={placement}
        invalid={Boolean(error)}
        disabled={state.disabled}
        className={cn(checkedLayout && (description || message) ? "flex-wrap" : undefined, className)}
      >
        {checkedLayout ? (
          <>
            {control}
            {fieldLabel}
          </>
        ) : (
          <>
            {fieldLabel}
            {control}
          </>
        )}
        {description === undefined ? null : (
          <FieldDescription className={checkedLayout ? "basis-full" : undefined}>{description}</FieldDescription>
        )}
        {message === undefined ? null : (
          <FieldError match className={checkedLayout ? "basis-full" : undefined}>
            {message}
          </FieldError>
        )}
      </Field>
    </FormFieldContext.Provider>
  )
}

export { FormField, formControlAdapters, useFormField }
export type { FormControlAdapter, FormFieldProps, FormFieldState }

"use client"

import {
  useFieldArray,
  useWatch,
  type ArrayPath,
  type FieldArray,
  type FieldPath,
  type FieldPathValue,
  type FieldValues,
  type UseFieldArrayProps,
  type UseFieldArrayReturn,
  type UseFormReturn,
} from "react-hook-form"

import { useFormContext } from "@/components/ui/form-context"

/**
 * The react-hook-form instance of the surrounding `Form`, typed by its input values: `trigger`, `setValue`,
 * `getValues`, `control`, `formState`. Its `watch` re-renders the Form, not the caller: read a live value with
 * `useFormWatch(name)` instead.
 */
function useFormInstance<Values extends FieldValues = FieldValues>(): UseFormReturn<Values> {
  return useFormContext("useFormInstance").form as unknown as UseFormReturn<Values>
}

/** react-hook-form's `useFieldArray` options without `name` and `control`; `keyName` names the rows' key property. */
type UseFormFieldArrayOptions<
  Values extends FieldValues,
  Name extends ArrayPath<Values>,
  KeyName extends string = "id",
> = Omit<UseFieldArrayProps<Values, Name, KeyName>, "name" | "control">

/** A field's live value, re-rendering only the caller: react-hook-form's `useWatch` bound to the surrounding `Form`. */
function useFormWatch<Values extends FieldValues = FieldValues, Name extends FieldPath<Values> = FieldPath<Values>>(
  name: Name,
): FieldPathValue<Values, Name> {
  const form = useFormContext("useFormWatch").form as unknown as UseFormReturn<Values>
  return useWatch<Values, Name>({ name, control: form.control })
}

/**
 * react-hook-form's `useFieldArray` bound to the surrounding `Form`. Key rows by `field.id`, never by index. When the
 * items carry their own `id`, pass `keyName: "fieldKey"` (any free name) and key rows by `field.fieldKey`:
 * react-hook-form writes its row key over the property `keyName` names.
 */
function useFormFieldArray<
  Values extends FieldValues = FieldValues,
  Name extends ArrayPath<Values> = ArrayPath<Values>,
  KeyName extends string = "id",
>(name: Name, options?: UseFormFieldArrayOptions<Values, Name, KeyName>): UseFieldArrayReturn<Values, Name, KeyName> {
  const form = useFormContext("useFormFieldArray").form as unknown as UseFormReturn<Values>
  return useFieldArray<Values, Name, KeyName>({
    ...options,
    name,
    control: form.control,
  })
}

export { useFormFieldArray, useFormInstance, useFormWatch }
export type { FieldArray, UseFormFieldArrayOptions }

import type { StandardSchemaV1 } from "@standard-schema/spec"

type FormIssueCode =
  | "required"
  | "minLength"
  | "maxLength"
  | "minItems"
  | "maxItems"
  | "min"
  | "max"
  | "email"
  | "url"
  | "pattern"
  | "invalid"
  | "server"
  | (string & {})

type FormIssue = {
  code: FormIssueCode
  /** The field's name, as a dot path like `address.city`; `root` for the form as a whole. */
  field: string
  /** The field's label, when it is a string. */
  label?: string
  /** Values the message may use, like `{ min: 3 }`. */
  params: Record<string, unknown>
  /** The schema's or the server's own text. */
  message?: string
}

/** A message: a string with `{param}` placeholders (`{label}` too), or a function of the issue. */
type FormMessage = string | ((issue: FormIssue) => string)

type FormMessageDictionary = Partial<Record<FormIssueCode, FormMessage>>

/** A dictionary, or a function that returns the text for an issue, `undefined` to fall back to the defaults. */
type FormMessages = FormMessageDictionary | ((issue: FormIssue) => string | undefined)

/** An error from your code or your server: plain text, or a code your `messages` translate. */
type FormErrorInput = string | { code: string; params?: Record<string, unknown>; message?: string }

type FormErrors = {
  fieldErrors?: Record<string, FormErrorInput>
  message?: FormErrorInput
}

const plural = (count: unknown, one: string, other: string) => (count === 1 ? one : other)

const formMessagesEn: FormMessageDictionary = {
  required: "This field is required.",
  minLength: ({ params }) => `Use at least ${String(params.min)} ${plural(params.min, "character", "characters")}.`,
  maxLength: ({ params }) => `Use at most ${String(params.max)} ${plural(params.max, "character", "characters")}.`,
  minItems: "Choose at least {min}.",
  maxItems: "Choose at most {max}.",
  min: "Enter {min} or more.",
  max: "Enter {max} or less.",
  email: "Enter a valid email address.",
  url: "Enter a valid URL.",
  pattern: "Use the expected format.",
}

const formMessagesEs: FormMessageDictionary = {
  required: "Este campo es obligatorio.",
  minLength: ({ params }) => `Escribe al menos ${String(params.min)} ${plural(params.min, "carácter", "caracteres")}.`,
  maxLength: ({ params }) =>
    `Escribe como máximo ${String(params.max)} ${plural(params.max, "carácter", "caracteres")}.`,
  minItems: "Elige al menos {min}.",
  maxItems: "Elige como máximo {max}.",
  min: "Introduce {min} o más.",
  max: "Introduce {max} o menos.",
  email: "Introduce un correo electrónico válido.",
  url: "Introduce una URL válida.",
  pattern: "Usa el formato indicado.",
}

function interpolate(template: string, issue: FormIssue) {
  return template.replace(/\{(\w+)\}/g, (match, key: string) => {
    if (key === "label") return issue.label ?? ""
    const value = issue.params[key]
    return value === undefined ? match : String(value)
  })
}

function fromLayer(layer: FormMessages | undefined, issue: FormIssue) {
  if (!layer) return undefined
  if (typeof layer === "function") return layer(issue)
  const message = layer[issue.code]
  if (message === undefined) return undefined
  return typeof message === "function" ? message(issue) : interpolate(message, issue)
}

/** The text for an issue: the first layer that has one, then English, then the issue's own message, then its code. */
function resolveFormMessage(issue: FormIssue, ...layers: (FormMessages | undefined)[]) {
  for (const layer of [...layers, formMessagesEn]) {
    const message = fromLayer(layer, issue)
    if (message !== undefined) return message
  }
  return issue.message ?? issue.code
}

/** Messages from a `t(key, params)` function (i18next, FormatJS, Lingui…): keys are `<prefix>.<code>`, unless the code already starts with the prefix. */
function createFormMessages(
  t: (key: string, params: Record<string, unknown>) => string | undefined,
  prefix = "form",
): (issue: FormIssue) => string | undefined {
  return (issue) => {
    const key = issue.code.startsWith(`${prefix}.`) ? issue.code : `${prefix}.${issue.code}`
    const text = t(key, { ...issue.params, field: issue.label })
    return text === undefined || text === key ? undefined : text
  }
}

// A message with no spaces and at least one dot reads as a translation key the schema author chose.
const translationKey = /^[A-Za-z_$][\w$-]*(\.[\w$-]+)+$/

const builtInCodes = new Set<string>([
  "required",
  "minLength",
  "maxLength",
  "minItems",
  "maxItems",
  "min",
  "max",
  "email",
  "url",
  "pattern",
  "invalid",
])

// Reserved so a coded message can't be read from prose: no schema author writes it at the start of a sentence.
const codedPrefix = "@@form:"

/**
 * A schema message that carries its code and params, for schemas whose issues have no codes, like Effect Schema:
 * `@@form:<code>` or `@@form:<code>|<JSON params>`. Any code round-trips, built-in or a dotted key. A plain dotted
 * key (`"form.name.taken"`) and the earlier `<code>|<JSON params>` still read as coded.
 */
function formIssueMessage(code: string, params?: Record<string, unknown>) {
  const head = `${codedPrefix}${code}`
  return params === undefined || Object.keys(params).length === 0 ? head : `${head}|${JSON.stringify(params)}`
}

function paramsFrom(json: string): Record<string, unknown> | undefined {
  try {
    const params: unknown = JSON.parse(json)
    if (params && typeof params === "object" && !Array.isArray(params)) return params as Record<string, unknown>
  } catch {
    return undefined
  }
  return undefined
}

function codedMessage(message: string): Pick<FormIssue, "code" | "params"> | undefined {
  const prefixed = message.startsWith(codedPrefix)
  const body = prefixed ? message.slice(codedPrefix.length) : message
  const split = body.indexOf("|")
  const code = split < 0 ? body : body.slice(0, split)
  if (prefixed) {
    if (!code) return undefined
    return { code, params: split < 0 ? {} : (paramsFrom(body.slice(split + 1)) ?? {}) }
  }
  if (!translationKey.test(code) && !(split >= 0 && builtInCodes.has(code))) return undefined
  if (split < 0) return { code, params: {} }
  const params = paramsFrom(body.slice(split + 1))
  return params && { code, params }
}

function isEmptyValue(value: unknown) {
  return value === undefined || value === null || value === "" || (Array.isArray(value) && value.length === 0)
}

function bound(value: unknown) {
  return typeof value === "bigint" ? Number(value) : value
}

function vendorCode(issue: Record<string, unknown>, value: unknown): Pick<FormIssue, "code" | "params"> | undefined {
  const code = issue.code
  const kind = issue.origin ?? issue.type
  const many = Array.isArray(value) || kind === "array" || kind === "set"
  const text = typeof value === "string" || kind === "string"
  if (code === "too_small") {
    const min = bound(issue.minimum)
    if (text && min === 1) return { code: "required", params: {} }
    return { code: many ? "minItems" : text ? "minLength" : "min", params: { min } }
  }
  if (code === "too_big") {
    const max = bound(issue.maximum)
    return { code: many ? "maxItems" : text ? "maxLength" : "max", params: { max } }
  }
  const format = code === "invalid_format" ? issue.format : code === "invalid_string" ? issue.validation : undefined
  if (format === "email" || format === "url") return { code: format, params: {} }
  if (format !== undefined) return { code: "pattern", params: { pattern: String(issue.pattern ?? format) } }

  switch (issue.type) {
    case "non_empty":
      return { code: "required", params: {} }
    case "min_length":
      return { code: many ? "minItems" : "minLength", params: { min: issue.requirement } }
    case "max_length":
      return { code: many ? "maxItems" : "maxLength", params: { max: issue.requirement } }
    case "min_value":
      return { code: "min", params: { min: issue.requirement } }
    case "max_value":
      return { code: "max", params: { max: issue.requirement } }
    case "email":
    case "url":
      return { code: issue.type, params: {} }
    case "regex":
      return { code: "pattern", params: { pattern: String(issue.requirement) } }
    default:
      return undefined
  }
}

function issuePath(issue: StandardSchemaV1.Issue) {
  if (!issue.path?.length) return "root"
  return issue.path.map((segment) => String(typeof segment === "object" ? segment.key : segment)).join(".")
}

function valueAt(values: unknown, path: string) {
  let current = values
  for (const key of path.split(".")) {
    if (current === null || typeof current !== "object") return undefined
    current = (current as Record<string, unknown>)[key]
  }
  return current
}

/**
 * Gives a Standard Schema issue a stable code: a coded message (`formIssueMessage`) as its code and params, with no
 * `message`; `required` for an empty value; the known Zod and Valibot validators with their bounds; else `invalid`
 * with the schema's message.
 */
function issueFromSchema(issue: StandardSchemaV1.Issue, values?: unknown): FormIssue {
  const field = issuePath(issue)
  const coded = codedMessage(issue.message)
  if (coded) return { ...coded, field, message: undefined }
  const value = field === "root" ? values : valueAt(values, field)
  const known =
    values !== undefined && isEmptyValue(value) && field !== "root"
      ? { code: "required", params: {} }
      : vendorCode(issue as unknown as Record<string, unknown>, value)
  return { ...(known ?? { code: "invalid", params: {} }), field, message: issue.message }
}

function issueFromInput(input: FormErrorInput, field: string): FormIssue {
  if (typeof input === "string") return { code: "server", field, params: {}, message: input }
  return { code: input.code, field, params: input.params ?? {}, message: input.message }
}

/** Throw it from `onSubmit`: its field errors go to their fields and its message to `FormRootError`. */
class FormServerError extends Error {
  fieldErrors: Record<string, FormErrorInput>
  code?: string
  params?: Record<string, unknown>

  constructor(message: FormErrorInput = "", fieldErrors: Record<string, FormErrorInput> = {}) {
    super(typeof message === "string" ? message : (message.message ?? message.code))
    this.name = "FormServerError"
    this.fieldErrors = fieldErrors
    if (typeof message !== "string") {
      this.code = message.code
      this.params = message.params
    }
  }
}

function isIssueList(value: unknown): value is readonly StandardSchemaV1.Issue[] {
  return Array.isArray(value) && value.every((item) => item && typeof item === "object" && "message" in item)
}

function toIssueInput(issue: FormIssue): FormErrorInput {
  return { code: issue.code, params: issue.params, message: issue.message }
}

/**
 * Reads errors in any of the shapes `onSubmit` may throw: a `FormServerError`, `{ fieldErrors, message }`, a Standard
 * Schema issue list or `{ issues }`. Anything else returns `undefined`.
 */
function toFormErrors(error: unknown): FormErrors | undefined {
  if (error instanceof FormServerError) {
    const message = error.code ? { code: error.code, params: error.params, message: error.message } : error.message
    return { fieldErrors: error.fieldErrors, message: message || undefined }
  }
  const issues = isIssueList(error)
    ? error
    : error && typeof error === "object" && isIssueList((error as { issues?: unknown }).issues)
      ? (error as { issues: readonly StandardSchemaV1.Issue[] }).issues
      : undefined
  if (issues) {
    const result: FormErrors = { fieldErrors: {} }
    for (const issue of issues) {
      const parsed = issueFromSchema(issue)
      if (parsed.field === "root") result.message ??= toIssueInput(parsed)
      else result.fieldErrors![parsed.field] ??= toIssueInput(parsed)
    }
    return result
  }
  if (error instanceof Error || !error || typeof error !== "object") return undefined
  const { fieldErrors, message } = error as FormErrors
  if (fieldErrors === undefined && message === undefined) return undefined
  return { fieldErrors, message }
}

export {
  FormServerError,
  createFormMessages,
  formIssueMessage,
  formMessagesEn,
  formMessagesEs,
  issueFromInput,
  issueFromSchema,
  issuePath,
  resolveFormMessage,
  toFormErrors,
}
export type { FormErrorInput, FormErrors, FormIssue, FormIssueCode, FormMessage, FormMessageDictionary, FormMessages }

import { definePrimitive } from "@ui-sdk/core"

type FormRootOptions = {
  /** Whether the form has an accessible name, so an agent can find it. */
  named?: boolean
  /** Whether submitting needs a person (a destructive submit): agents then press the submit button instead. */
  confirm?: boolean
  onResetRequest?: () => void
}

const formRoot = definePrimitive({
  name: "form",
  options: { named: "boolean", confirm: "boolean", onResetRequest: "callback" },
  state: (options: FormRootOptions) => ({ named: Boolean(options.named), confirm: Boolean(options.confirm) }),
  sync: (options) => ({ named: Boolean(options.named), confirm: Boolean(options.confirm) }),
  api: (context) => ({
    submit() {
      const form = context.element("root")
      if (!(form instanceof HTMLFormElement)) return false
      form.requestSubmit()
      return true
    },
    reset() {
      const onResetRequest = context.options().onResetRequest
      if (!onResetRequest) return false
      onResetRequest()
      return true
    },
  }),
  slots: (slot) => ({
    root: slot({}),
  }),
  agent: { actions: ["submit", "reset"], shown: (state) => state.named && !state.confirm },
})

export { formRoot }
export type { FormRootOptions }

"use client"

import { useEffect, useEffectEvent, type RefObject } from "react"

/** Calls `onChange` with `value` once mounted and whenever it changes, never because `onChange` itself changed. */
function useReportChange<Value>(value: Value, onChange: ((value: Value) => void) | undefined) {
  const report = useEffectEvent((next: Value) => onChange?.(next))
  useEffect(() => report(value), [value])
}

/** Disabling the fields drops focus to the body; give it back to `restoreFocusRef` once they are enabled again. */
function useRestoreFocusAfterPending(pending: boolean, restoreFocusRef: RefObject<Element | null>) {
  useEffect(() => {
    const previous = restoreFocusRef.current
    if (pending || !(previous instanceof HTMLElement)) return
    restoreFocusRef.current = null
    if (document.activeElement === document.body || document.activeElement === null) previous.focus()
  }, [pending, restoreFocusRef])
}

/** Runs `focus` after the render that bumps `request` past zero, once the invalid fields are on screen. */
function useFocusRequest(request: number, focus: () => void) {
  const onRequest = useEffectEvent(focus)
  useEffect(() => {
    if (request !== 0) onRequest()
  }, [request])
}

/** Holds a form-wide flag at `value` while the caller is mounted, and resets it to `false` after. */
function useFormFlag(set: (value: boolean) => void, value: boolean) {
  const apply = useEffectEvent(set)
  useEffect(() => {
    apply(value)
    return () => apply(false)
  }, [value])
}

/** Records a rendered field and its text label, so errors for it land on the field rather than the root. */
function useFieldRegistration(fields: Map<string, string | undefined>, name: string, label: string | undefined) {
  useEffect(() => {
    fields.set(name, label)
    return () => {
      fields.delete(name)
    }
  }, [fields, name, label])
}

export { useFieldRegistration, useFocusRequest, useFormFlag, useReportChange, useRestoreFocusAfterPending }
